#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    // Long division; a repeated remainder marks where the cycle starts.
    vector<int> firstPos(n, -1);
    string digits;
    int remainder = 1;
    while (remainder != 0 && firstPos[remainder] < 0) {
        firstPos[remainder] = digits.size();
        remainder *= 10;
        digits += char('0' + remainder / n);
        remainder %= n;
    }
    string prefix, cycle;
    if (remainder == 0) prefix = digits, cycle = "0";
    else prefix = digits.substr(0, firstPos[remainder]), cycle = digits.substr(firstPos[remainder]);
    cout << "0." << prefix << cycle << " " << cycle << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] firstPos = new int[n];
        Arrays.fill(firstPos, -1);
        StringBuilder digits = new StringBuilder();
        int remainder = 1;
        while (remainder != 0 && firstPos[remainder] < 0) {
            firstPos[remainder] = digits.length();
            remainder *= 10;
            digits.append((char) ('0' + remainder / n));
            remainder %= n;
        }
        String prefix, cycle;
        if (remainder == 0) {
            prefix = digits.toString();
            cycle = "0";
        } else {
            prefix = digits.substring(0, firstPos[remainder]);
            cycle = digits.substring(firstPos[remainder]);
        }
        System.out.print("0." + prefix + cycle + " " + cycle + "\n");
    }
}
